    """'0-306-40615-2' -> True."""
    # Remove all dashes
    cleaned = s.replace('-', '')

    # Must be exactly 10 characters
    if len(cleaned) != 10:
        return False

    # First 9 must be digits
    for i in range(9):
        if not cleaned[i].isdigit():
            return False

    # Last character must be digit or 'X'
    last_char = cleaned[9]
    if last_char == 'X':
        last_value = 10
    elif last_char.isdigit():
        last_value = int(last_char)
    else:
        return False

    # Calculate weighted sum: (i+1) * digit for i=0..9
    total = 0
    for i in range(9):
        total += (i + 1) * int(cleaned[i])
    total += 10 * last_value

    # Sum must be divisible by 11
    return total % 11 == 0"}

