            return result

        # Handle addition/subtraction (lowest precedence)
        left = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        # Handle multiplication/division (higher precedence)
        left = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                left = left * right
            else:
                left = left // right  # integer division (floor)
        return left

    def parse_factor():
        # Handle numbers
        if peek() and peek().isdigit():
