{"path": "solution.py", "content": "def validate_isbn10(s):
    """'0-306-40615-2' -> True."""
    # Remove dashes
    s = s.replace('-', '')

    # Must be exactly 10 characters
    if len(s) != 10:
        return False

    # First 9 must be digits
    for i in range(9):
        if not s[i].isdigit():
            return False

    # Last character must be digit or 'X'
    last = s[9]
    if last == 'X':
        last_val = 10
    elif last.isdigit():
        last_val = int(last)
    else:
        return False

    # Calculate weighted sum: (i+1) * digit for i=0..9
    total = 0
    for i in range(9):
        total += (i + 1) * int(s[i])
    total += 10 * last_val

    # Must be divisible by 11
    return total % 11 == 0"}

