{"path": "solution.py", "content": "def validate_isbn10(s):
    """'0-306-40615-2' -> True."""
    # Remove dashes
    cleaned = s.replace('-', '')

    # Must be exactly 10 characters
    if len(cleaned) != 10:
        return False

    # First 9 must be digits, last must be digit or 'X'
    for i in range(9):
        if not cleaned[i].isdigit():
            return False

    last_char = cleaned[9]
    if not (last_char.isdigit() or last_char == 'X'):
        return False

    # Calculate weighted sum
    total = 0
    for i in range(9):
        digit = int(cleaned[i])
        total += (i + 1) * digit

    # Handle last character
    if last_char == 'X':
        total += 10 * 10  # (9+1) * 10 = 100
    else:
        total += 10 * int(last_char)

    # Must be divisible by 11
    return total % 11 == 0"}

