    cleaned = s.replace('-', '')

    # Must be exactly 10 characters
    if len(cleaned) != 10:
        return False

    # First 9 must be digits
    for i in range(9):
        if not cleaned[i].isdigit():
            return False

    # Last character must be digit or 'X'
    last_char = cleaned[9]
    if not (last_char.isdigit() or last_char == 'X'):
        return False

    # Calculate weighted sum
    total = 0
    for i in range(10):
        char = cleaned[i]
        if char == 'X':
            value = 10
        else:
            value = int(char)
        total += (i + 1) * value

