    """[0,2,4,5,6,9] -> '0,2,4-6,9'."""
    if not nums:
        return ""

    parts = []
    start = nums[0]
    prev = nums[0]

    for n in nums[1:]:
        if n == prev + 1:
            prev = n
            continue
        # run ended at prev
        if prev - start >= 2:
            parts.append("%d-%d" % (start, prev))
        elif prev - start == 1:
            parts.append("%d,%d" % (start, prev))
        else:
            parts.append(str(start))
        start = n
        prev = n

    # flush final run
    if prev - start >= 2:
        parts.append("%d-%d" % (start, prev))
    elif prev - start == 1:
        parts.append("%d,%d" % (start, prev))
    else:
        parts.append(str(start))

    return ",".join(parts)
"}

