    start = 0
    n = len(nums)

    for i in range(1, n + 1):
        # A run ends when we reach the end or the sequence breaks.
        if i == n or nums[i] != nums[i - 1] + 1:
            run_len = i - start
            if run_len >= 3:
                parts.append("{}-{}".format(nums[start], nums[i - 1]))
            elif run_len == 2:
                parts.append(str(nums[start]))
                parts.append(str(nums[i - 1]))
            else:
                parts.append(str(nums[start]))
            start = i

    return ",".join(parts)
