{"path": "solution.py", "content": "def validate_isbn10(s):
    """'0-306-40615-2' -> True."""
    if not isinstance(s, str):
        return False

    # Dashes may appear anywhere and are ignored.
    t = s.replace("-", "")

    # Exactly 10 characters after removing dashes.
    if len(t) != 10:
        return False

    # First 9 characters must be digits.
    for ch in t[:9]:
        if not ch.isdigit() or not ch.isascii():
            return False

    # Last character must be a digit or 'X' (worth 10).
    last = t[9]
    if last == "X":
        last_val = 10
    elif last.isdigit() and last.isascii():
        last_val = int(last)
    else:
        return False

    # Weighted sum: (i+1) * digit for i = 0..9 must be divisible by 11.
    total = sum((i + 1) * int(t[i]) for i in range(9))
    total += 10 * last_val

    return total % 11 == 0
"}

