            return s[pos[0]]
        return None

    def consume():
        if pos[0] < len(s):
            ch = s[pos[0]]
            pos[0] += 1
            return ch
        return None

    def parse_expression():
        # Handle parentheses
        if peek() == '(':
            consume()  # consume '('
            result = parse_expression()
            consume()  # consume ')'
            return result

        # Handle addition/subtraction (lowest precedence)
        left = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        # Handle multiplication/division (higher precedence)
        left = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                left = left * right
            else:
                left = left // right  # integer division (floor)
        return left

    def parse_factor():
        # Handle numbers
        if peek() and peek().isdigit():
