{"content": "def range_extraction(nums):
    """[0,2,4,5,6,9] -> '0,2,4-6,9'."""
    if not nums:
        return ""

    parts = []
    run_start = 0  # index where the current consecutive run begins

    for i in range(1, len(nums) + 1):
        # A run ends when we're at the end of the list or the streak breaks
        if i == len(nums) or nums[i] != nums[i - 1] + 1:
            run = nums[run_start:i]
            if len(run) >= 3:
                parts.append(f"{run[0]}-{run[-1]}")
            else:
                # runs of length 1 or 2 are listed individually
                parts.extend(str(n) for n in run)
            run_start = i

    return ",".join(parts)
