    """'0-306-40615-2' -> True."""
    # Dashes are ignored anywhere in the string.
    chars = [c for c in s if c != '-']

    # Must be exactly 10 characters after removing dashes.
    if len(chars) != 10:
        return False

    # First 9 must be digits; last may be a digit or 'X' (worth 10).
    total = 0
    for i, c in enumerate(chars):
        if c.isdigit():
            v = int(c)
        elif c == 'X' and i == 9:
            v = 10
        else:
            return False
        total += (i + 1) * v

    return total % 11 == 0
