    """[0,2,4,5,6,9] -> '0,2,4-6,9'."""
    if not nums:
        return ""
    parts = []
    start = nums[0]
    prev = nums[0]
    for n in nums[1:]:
        if n == prev + 1:
            prev = n
        else:
            # close the current run
            if prev - start >= 2:
                parts.append(f"{start}-{prev}")
            elif prev - start == 1:
                parts.append(f"{start}")
                parts.append(f"{prev}")
            else:
                parts.append(f"{start}")
            start = n
            prev = n
    # close final run
    if prev - start >= 2:
        parts.append(f"{start}-{prev}")
    elif prev - start == 1:
        pairs = [f"{start}", f"{prev}"]
        parts.extend(pairs)
    else:
        parts.append(f"{start}")
    return ",".join(parts)"}

