{"path": "solution.py", "content": "def smart_title(s):
    """'the war of the worlds' -> 'The War of the Worlds'.

    Title-case every word, except small words (a, an, the, of, in, on,
    to, for) stay lowercase. The first and last words are always
    capitalized. Words are space-separated.
    """
    SMALL_WORDS = {"a", "an", "the", "of", "in", "on", "to", "for"}

    def capitalize(word):
        return word[:1].upper() + word[1:].lower()

    # Split on single spaces so original spacing structure is preserved.
    tokens = s.split(" ")

    # Positions of the actual (non-empty) words.
    word_positions = [i for i, t in enumerate(tokens) if t]
    if not word_positions:
        return s

    first = word_positions[0]
    last = word_positions[-1]

    result = []
    for i, token in enumerate(tokens):
        if not token:
            # Preserve empty tokens (consecutive/leading/trailing spaces).
            result.append(token)
        elif i == first or i == last or token.lower() not in SMALL_WORDS:
            result.append(capitalize(token))
        else:
            # Small word in the middle stays lowercase.
            result.append(token.lower())

    return " ".join(result)
"}

