{"content": "def range_extraction(nums):
    """Given a sorted list of unique ints, return the compact range string.

    Runs of >= 3 consecutive integers are rendered as 'a-b'; everything
    else is listed individually, all comma-separated.
    """
    if not nums:
        return ""

    parts = []
    run_start = 0  # index where the current run of consecutive ints began

    for i in range(1, len(nums) + 1):
        # A run ends when we reach the end of the list or hit a gap.
        if i == len(nums) or nums[i] != nums[i - 1] + 1:
            run_length = i - run_start
            if run_length >= 3:
                parts.append("{}-{}".format(nums[run_start], nums[i - 1]))
            else:
                # Run of 1 or 2: list each element individually.
                parts.extend(str(nums[j]) for j in range(run_start, i))
            run_start = i

    return ",".join(parts)
