    Small words: a, an, the, of, in, on, to, for.
    The first and last words are always capitalized.
    Words are space-separated.
    """
    small_words = {"a", "an", "the", "of", "in", "on", "to", "for"}

    words = s.split(" ")
    if not words:
        return s

    result = []
    n = len(words)
    for i, word in enumerate(words):
        if not word:
            # Preserve empty tokens (e.g., consecutive spaces)
            result.append(word)
            continue
        lower = word.lower()
        is_first = (i == 0)
        is_last = (i == n - 1)
        if lower in small_words and not is_first and not is_last:
            result.append(lower)
        else:
            result.append(lower.capitalize())
    return " ".join(result)
