{"path": "solution.py", "content": "def range_extraction(nums):
    """Given a sorted list of unique ints, return the compact range string.

    Runs of >= 3 consecutive ints become 'a-b'; others are listed singly,
    comma-separated. E.g. [-6,-3,-2,-1,0,1,3,4,5,7,8,10,11,14]
    -> '-6,-3-1,3-5,7,8,10,11,14'.
    """
    if not nums:
        return ""

    parts = []
    run_start = 0  # index where the current run of consecutive ints began

    for i in range(1, len(nums) + 1):
        # Run ends when we're past the last element or there's a gap
        if i == len(nums) or nums[i] != nums[i - 1] + 1:
            run_length = i - run_start
            if run_length >= 3:
                parts.append("{}-{}".format(nums[run_start], nums[i - 1]))
            elif run_length == 2:
                parts.append(str(nums[run_start]))
                parts.append(str(nums[run_start + 1]))
            else:
                parts.append(str(nums[run_start]))
            run_start = i

    return ",".join(parts)
