    """Title-case s, except small words stay lowercase.

    Small words: a, an, the, of, in, on, to, for.
    The first and last word are always capitalized.
    Words are space-separated.
    """
    small_words = {"a", "an", "the", "of", "in", "on", "to", "for"}

    words = s.split(" ")
    if not words:
        return s

