{"content": "def validate_isbn10(s):
    """'0-306-40615-2' -> True."""
    # Ignore dashes anywhere in the string.
    if not isinstance(s, str):
        return False
    cleaned = s.replace("-", "")

    # Must be exactly 10 significant characters.
    if len(cleaned) != 10:
        return False

    # First 9 characters must be digits.
    for ch in cleaned[:9]:
        if not ("0" <= ch <= "9"):
            return False

    # Last character: digit, or 'X' worth 10.
    last = cleaned[9]
    if "0" <= last <= "9":
        last_value = int(last)
    elif last == "X":
        last_value = 10
    else:
        return False

    # Weighted sum: (i+1) * digit for i = 0..9, must be divisible by 11.
    total = 0
    for i in range(9):
        total += (i + 1) * int(cleaned[i])
    total += 10 * last_value

    return total % 11 == 0
