    """[0,2,4,5,6,9] -> '0,2,4-6,9'."""
    if not nums:
        return ""

    parts = []
    start = nums[0]
    prev = nums[0]

    for x in nums[1:]:
        if x == prev + 1:
            # Still in a consecutive run
            prev = x
        else:
            # Run broken: emit [start, prev]
            if prev - start >= 2:
                parts.append(f"{start}-{prev}")
            elif prev - start == 1:
                parts.append(f"{start}")
                parts.append(f"{prev}")
            else:
                parts.append(f"{start}")
            start = x
            prev = x

    # Emit the final run
    if prev - start >= 2:
        parts.append(f"{start}-{prev}")
    elif prev - start == 1:
        parts.append(f"{start}")
