        while j < len(nums) and nums[j] == end + 1:
            end = nums[j]
            j += 1

        # Check if we have a range of 3 or more consecutive numbers
        if end - start >= 2:  # At least 3 numbers (start, start+1, start+2)
            result.append(f"{start}-{end}")
        else:
            # List individual numbers
            for k in range(start, end + 1):
                result.append(str(k))

        # Move to the next number after the current range
        i = j

    return ",".join(result)

