def range_extraction(nums):
    """[0,2,4,5,6,9] -> '0,2,4-6,9'."""
    if not nums:
        return ""

    result = []
    i = 0
    n = len(nums)

    while i < n:
        # Start of a potential range
        start = nums[i]
        j = i + 1

        # Find how far the consecutive run goes
        while j < n and nums[j] == nums[j-1] + 1:
            j += 1

        # Range is from i to j-1 (inclusive)
        end = nums[j-1]
        count = j - i  # Number of elements in this run

        if count >= 3:
            # Run of 3 or more: format as "a-b"
            result.append(f"{start}-{end}")
        else:
            # Run of 1 or 2: list each individually
            for k in range(i, j):
                result.append(str(nums[k]))

        i = j

    return ",".join(result)

