{"path": "solution.py", "content": "def eval_arith(s):
    """eval_arith('2+3*4') == 14, eval_arith('(2+4)/3') == 2."""
    s = s.strip()
    pos = [0]  # Use list to allow modification in nested functions

    def peek():
        if pos[0] < len(s):
            return s[pos[0]]
        return None

    def consume():
        if pos[0] < len(s):
            ch = s[pos[0]]
            pos[0] += 1
            return ch
        return None

    def parse_expression():
        # Handle parentheses
        if peek() == '(':
            consume()  # consume '('
            result = parse_expression()
            consume()  # consume ')'
            return result

        # Handle addition/subtraction (lowest precedence)
        left = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        # Handle multiplication/division (higher precedence)
        left = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                left = left * right
            else:
                left = left // right  # integer division (floor)
        return left

    def parse_factor():
        # Handle numbers
        if peek() and peek().isdigit():
            start = pos[0]
            while pos[0] < len(s) and s[pos[0]].isdigit():
                pos[0] += 1
            return int(s[start:pos[0]])

        # Handle unary minus
        if peek() == '-':
            consume()
            return -parse_factor()

        if peek() == '+':
            consume()
            return parse_factor()

        raise ValueError(f"Unexpected character: {peek()}")

    result = parse_expression()
    return result"}

