    """[0,2,4,5,6,9] -> '0,2,4-6,9'."""
    if not nums:
        return ""

    result = []
    i = 0
    n = len(nums)

    while i < n:
        start = nums[i]
        # Find the end of the consecutive run
        j = i
        while j + 1 < n and nums[j + 1] == nums[j] + 1:
            j += 1

        end = nums[j]

        # If the run has 3 or more numbers, format as 'start-end'
        if end - start >= 2:
            result.append(f"{start}-{end}")
        else:
            # Otherwise, list each number individually
            for k in range(start, end + 1):
                result.append(str(k))

        i = j + 1

    return ",".join(result)"}

