{"path": "solution.py", "content": "def validate_isbn10(s):
    """'0-306-40615-2' -> True."""
    # Remove dashes
    s = s.replace('-', '')

    # Must be exactly 10 characters
    if len(s) != 10:
        return False

    # First 9 must be digits
    for i in range(9):
        if not s[i].isdigit():
            return False

    # Last character must be digit or 'X'
    last = s[9]
    if not (last.isdigit() or last == 'X'):
        return False

    # Calculate weighted sum: (i+1) * digit for i=0..9
    total = 0
    for i in range(10):
        if s[i] == 'X':
            digit = 10
        else:
            digit = int(s[i])
        total += (i + 1) * digit

    # Must be divisible by 11
    return total % 11 == 0"}

